// Detectar acciones especiales en la respuesta del AI
const output = $json.output || '';

// Función helper para obtener datos de nodos que pueden no estar ejecutados
function getFromNode(nodeName, field) {
  try {
    const node = $(nodeName);
    if (node && node.first && node.first()) {
      return node.first().json[field];
    }
  } catch (e) {
    // Nodo no ejecutado
  }
  return null;
}

// Función para verificar si un nodo fue ejecutado
function wasNodeExecuted(nodeName) {
  try {
    const node = $(nodeName);
    return node && node.isExecuted;
  } catch (e) {
    return false;
  }
}

// Detectar si el mensaje original vino de audio
const isFromAudio = wasNodeExecuted('Merge Audio Data');

// Obtener phoneNumber y phoneNumberId de cualquier fuente disponible
const phoneNumber = $json.phoneNumber || 
  getFromNode('Merge Data', 'phoneNumber') || 
  getFromNode('Merge Audio Data', 'phoneNumber') || 
  getFromNode('Merge Image Data', 'phoneNumber') || 
  getFromNode('Button to Text', 'phoneNumber');

const phoneNumberId = $json.phoneNumberId || 
  getFromNode('Merge Data', 'phoneNumberId') || 
  getFromNode('Merge Audio Data', 'phoneNumberId') || 
  getFromNode('Merge Image Data', 'phoneNumberId') || 
  getFromNode('Button to Text', 'phoneNumberId');

let action = 'send_text';
let cleanMessage = output;

// Detectar acciones especiales
if (output.includes('<<ACTION:SHOW_CALENDAR>>')) {
  action = 'show_calendar';
  cleanMessage = output.replace('<<ACTION:SHOW_CALENDAR>>', '').trim();
} else if (output.includes('<<ACTION:CANCEL_APPOINTMENT>>')) {
  action = 'cancel_appointment';
  cleanMessage = output.replace('<<ACTION:CANCEL_APPOINTMENT>>', '').trim();
} else if (output.includes('<<ACTION:RESCHEDULE_APPOINTMENT>>')) {
  action = 'reschedule_appointment';
  cleanMessage = output.replace('<<ACTION:RESCHEDULE_APPOINTMENT>>', '').trim();
} else if (output.includes('<<ACTION:ESCALATE_SUPPORT>>')) {
  action = 'escalate_support';
  cleanMessage = output.replace('<<ACTION:ESCALATE_SUPPORT>>', '').trim();
} else if (output.includes('<<ACTION:SHOW_PLANS>>')) {
  action = 'show_plans';
  cleanMessage = output.replace('<<ACTION:SHOW_PLANS>>', '').trim();
} else if (isFromAudio) {
  // Si es respuesta de texto normal y el usuario envió audio, responder con audio
  action = 'send_audio';
}

return {
  json: {
    action: action,
    output: cleanMessage,
    phoneNumber: phoneNumber,
    phoneNumberId: phoneNumberId,
    isFromAudio: isFromAudio
  }
};

// Generar días disponibles validando horarios y feriados
const config = $('Get Appointments Config').first().json;

// Obtener phoneNumber/phoneNumberId del input (puede venir de diferentes flujos)
let phoneNumber, phoneNumberId, contactName;

// Intentar obtener de Route Action (flujo normal de booking)
try {
  const routeData = $('Route Action').first().json;
  phoneNumber = routeData.phoneNumber;
  phoneNumberId = routeData.phoneNumberId;
  contactName = routeData.contactName;
} catch (e) {}

// Si no se obtuvo, intentar de Parse Reschedule Event (flujo de reprogramación simplificado)
if (!phoneNumber) {
  try {
    const parseData = $('Parse Reschedule Event').first().json;
    phoneNumber = parseData.phoneNumber;
    phoneNumberId = parseData.phoneNumberId;
    contactName = parseData.clientName;
  } catch (e) {}
}

// Si no se obtuvo, intentar de Parse Event To Delete (flujo antiguo)
if (!phoneNumber) {
  try {
    const parseData = $('Parse Event To Delete').first().json;
    phoneNumber = parseData.phoneNumber;
    phoneNumberId = parseData.phoneNumberId;
    contactName = parseData.clientName;
  } catch (e) {}
}

// Si todavía no hay, usar el input directo (desde Set Reschedule Data u otro)
if (!phoneNumber) {
  const inputData = $input.first().json;
  phoneNumber = inputData.phoneNumber;
  phoneNumberId = inputData.phoneNumberId;
  contactName = inputData.contactName || inputData.clientName;
}

const weekSchedule = config.data?.weekSchedule || {};
const holidays = config.data?.holidays || [];

const dayNames = ['sunday', 'monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday'];
const dayNamesES = ['Dom', 'Lun', 'Mar', 'Mié', 'Jue', 'Vie', 'Sáb'];
const monthsES = ['ene', 'feb', 'mar', 'abr', 'may', 'jun', 'jul', 'ago', 'sep', 'oct', 'nov', 'dic'];

const now = DateTime.now().setZone('America/Santiago');
const days = [];
let checkDate = now;
let attempts = 0;

while (days.length < 3 && attempts < 30) {
  checkDate = checkDate.plus({ days: 1 });
  attempts++;

  const dayOfWeek = checkDate.weekday % 7;
  const dayName = dayNames[dayOfWeek];
  const dateKey = checkDate.toFormat('yyyy-MM-dd');

  // Verificar si el día está habilitado
  const dayConfig = weekSchedule[dayName] || { enabled: false };
  if (!dayConfig.enabled) continue;

  // Verificar si es feriado
  if (holidays.includes(dateKey)) continue;

  days.push({
    date: dateKey,
    display: `${dayNamesES[dayOfWeek]} ${checkDate.day} ${monthsES[checkDate.month - 1]}`,
    btnId: `day_${dateKey}`
  });
}

return {
  json: {
    phoneNumber: phoneNumber,
    phoneNumberId: phoneNumberId,
    contactName: contactName,
    availableDays: days
  }
};

