      hasAvailability: false,
      message: input.reason === 'Holiday' ? 'Lo siento, ese día es feriado.' : 
               input.reason === 'Day disabled' ? 'Lo siento, no hay atención ese día.' :
               'Lo siento, no hay horarios disponibles para ese día.'
    }
  };
}

// Obtener horarios de trabajo y ocupados desde WordPress
const workingHours = input.workingHours || { start: '09:00', end: '18:00' };
const busySlots = input.busySlots || [];

// Generar todos los slots del día
const [startHour] = workingHours.start.split(':').map(Number);
const [endHour] = workingHours.end.split(':').map(Number);

const allSlots = [];
for (let hour = startHour; hour < endHour; hour++) {
  allSlots.push(`${hour.toString().padStart(2, '0')}:00`);
}

// Filtrar horarios disponibles (no ocupados en BD)
const availableSlots = allSlots.filter(slot => !busySlots.includes(slot));

// Tomar los primeros 3 disponibles
const slotsToShow = availableSlots.slice(0, 3);

// Si no hay horarios disponibles
if (slotsToShow.length === 0) {
  return {
    json: {
      ...inputData,
      hasAvailability: false,
      message: 'Lo siento, no hay horarios disponibles para ese día. Por favor intenta con otro día.'
    }
  };
